  $steps=['Create or use a separate Google Maps Platform API key for this importer.','Set Application restrictions to IP addresses (server-side), not Websites / HTTP referrers.','Add the public outbound IP address used by this hosting server.','Under API restrictions, allow Places API (New).','Save that key in the Server Places API key field below, then run Test Server Connection.'];
 }elseif(str_contains($m,'not authorized')||str_contains($m,'permission_denied')||str_contains($m,'api key')){
  $type='authorization';$title='Google key authorization needs attention';
  $steps=['Confirm Places API (New) is enabled in the same Google Cloud project.','Confirm billing is active for the Google Maps Platform project.','Use an IP-restricted server key for the importer.','Restrict the key to Places API (New), then test again.'];
 }elseif(str_contains($m,'quota')||str_contains($m,'resource_exhausted')){
  $type='quota';$title='Google Places quota or billing limit reached';
  $steps=['Check Google Maps Platform quota and billing.','Reduce batch size if needed.','Retry after quota becomes available.'];
 }
