function bs1270_public_url_ok(string $url): bool {if(!filter_var($url,FILTER_VALIDATE_URL))return false;$p=parse_url($url);if(!in_array(strtolower((string)($p['scheme']??'')),['http','https'],true))return false;$host=(string)($p['host']??'');if($host==='')return false;$ip=gethostbyname($host);if(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)===false)return false;return true;}
function bs1270_flat_jsonld($node,array &$out): void {if(!is_array($node))return;if(array_is_list($node)){foreach($node as $n)bs1270_flat_jsonld($n,$out);return;}if(isset($node['@graph']))bs1270_flat_jsonld($node['@graph'],$out);$type=$node['@type']??'';$types=is_array($type)?$type:[$type];foreach($types as $t){$t=strtolower((string)$t);if(str_contains($t,'localbusiness')||in_array($t,['organization','store','restaurant','medicalbusiness','professionalservice'],true)){$out[]=$node;break;}}}
function bs1270_address_text($a): string {if(is_string($a))return trim($a);if(!is_array($a))return '';$parts=[];foreach(['streetAddress','addressLocality','addressRegion','postalCode','addressCountry'] as $k)if(!empty($a[$k]))$parts[]=(string)$a[$k];return trim(implode(', ',$parts));}
function bs1270_fetch_official_website(string $url,string $googleName=''): array {if(!bs1270_public_url_ok($url))return ['verified'=>false,'error'=>'Website URL is not safe/valid.'];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>3,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>10,CURLOPT_USERAGENT=>'ShahkotPK Business Verifier/12.7 (+https://shahkotpk.com)',CURLOPT_ENCODING=>'',CURLOPT_MAXFILESIZE=>2500000]);$html=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$final=(string)curl_getinfo($ch,CURLINFO_EFFECTIVE_URL);$ctype=(string)curl_getinfo($ch,CURLINFO_CONTENT_TYPE);curl_close($ch);if(!is_string($html)||$code<200||$code>=400||strlen($html)>3000000||(!str_contains(strtolower($ctype),'html')&&$ctype!==''))return ['verified'=>false,'error'=>'Official website could not be verified.'];libxml_use_internal_errors(true);$dom=new DOMDocument();@$dom->loadHTML($html);$xp=new DOMXPath($dom);$nodes=[];foreach($xp->query('//script[@type="application/ld+json"]')?:[] as $n){$j=json_decode(trim((string)$n->textContent),true);if(is_array($j))bs1270_flat_jsonld($j,$nodes);} $best=$nodes[0]??[];$title=trim((string)($best['name']??''));if($title===''&&($t=$xp->query('//meta[@property="og:site_name"]/@content')->item(0)))$title=trim((string)$t->nodeValue);if($title===''&&($t=$xp->query('//title')->item(0)))$title=trim(preg_replace('/\s+/',' ',(string)$t->textContent));$phone=trim((string)($best['telephone']??''));if($phone===''&&($n=$xp->query('//a[starts-with(@href,"tel:")]/@href')->item(0)))$phone=preg_replace('/^tel:/i','',trim((string)$n->nodeValue));$email=trim((string)($best['email']??''));if($email===''&&($n=$xp->query('//a[starts-with(@href,"mailto:")]/@href')->item(0)))$email=preg_replace('/^mailto:/i','',trim((string)$n->nodeValue));$address=bs1270_address_text($best['address']??'');$image='';$im=$best['image']??'';if(is_array($im))$im=$im[0]??'';if(is_array($im))$im=$im['url']??'';$image=trim((string)$im);if($image===''&&($n=$xp->query('//meta[@property="og:image"]/@content')->item(0)))$image=trim((string)$n->nodeValue);if($image!==''&&!filter_var($image,FILTER_VALIDATE_URL))$image='';$lat='';$lng='';if(isset($best['geo'])&&is_array($best['geo'])){$lat=(string)($best['geo']['latitude']??'');$lng=(string)($best['geo']['longitude']??'');}$text=mb_strtolower(strip_tags($html));$city=str_contains($text,'shahkot')||str_contains($text,'shah kot');$nameScore=0;if($googleName!==''&&$title!==''){similar_text(mb_strtolower($googleName),mb_strtolower($title),$nameScore);}elseif($title!=='')$nameScore=70;$verified=$city&&$title!==''&&($nameScore>=45||$googleName==='');return ['verified'=>$verified,'name'=>$title,'phone'=>$phone,'email'=>$email,'address'=>$address,'website'=>$final?:$url,'image'=>$image,'latitude'=>$lat,'longitude'=>$lng,'city_match'=>$city,'name_score'=>(int)round($nameScore),'error'=>$verified?'':'Website did not confidently match a Shahkot business.'];}
function bs1270_live_candidate(int $candidateId): array {$c=bs1270_candidate_by_id($candidateId);if(!$c)throw new RuntimeException('Candidate not found.');$g=bs1270_google_detail((string)$c['provider_place_id']);$geo=bs1270_shahkot_check($g);$web=['verified'=>false,'error'=>'No official website listed.'];$url=trim((string)($g['websiteUri']??''));if($url!==''&&bs1270_public_url_ok($url))$web=bs1270_fetch_official_website($url,(string)($g['displayName']['text']??''));$score=0;$score+=$geo['ok']?45:0;$score+=!empty($g['nationalPhoneNumber'])?10:0;$score+=!empty($g['location'])?10:0;$score+=!empty($g['displayName']['text'])?5:0;$score+=!empty($web['verified'])?30:0;$score=min(100,$score);$match=!empty($web['verified'])?bs1270_existing_match($web,$g):0;bs1270_update('business_source_candidates_v1270',$candidateId,['confidence'=>$score,'website_verified'=>!empty($web['verified'])?1:0,'distance_m'=>$geo['distance_m'],'matched_business_id'=>$match?:null,'status'=>$geo['ok']?($match?'matched':'verified'):'outside_city','last_error'=>$geo['ok']?(string)($web['error']??''):'Outside strict Shahkot boundary','last_checked_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);return ['candidate'=>$c,'google'=>$g,'geo'=>$geo,'website'=>$web,'confidence'=>$score,'matched_business_id'=>$match];}
function bs1270_random_password(): string {$chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';$o='';for($i=0;$i<16;$i++)$o.=$chars[random_int(0,strlen($chars)-1)];return $o;}
function bs1270_user_create(string $businessName,array $web,string $temp): int {if(!bs1270_table('users'))throw new RuntimeException('Users table unavailable.');$cols=bs1270_cols('users');$phone=trim((string)($web['phone']??''));$email=trim((string)($web['email']??''));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$email='';if($email!==''&&isset($cols['email'])){try{$q=db()->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$q->execute([$email]);if($u=(int)($q->fetchColumn()?:0))return $u;}catch(Throwable $e){}}if($phone!==''&&isset($cols['phone'])){try{$q=db()->query("SELECT id,phone FROM users WHERE phone IS NOT NULL AND phone<>'' ORDER BY id DESC LIMIT 1000");foreach($q->fetchAll() as $r)if(bs1270_norm_phone((string)$r['phone'])===bs1270_norm_phone($phone))return (int)$r['id'];}catch(Throwable $e){}}if($email==='')$email='import+'.substr(hash('sha256',$businessName.'|'.$phone.'|'.microtime(true)),0,18).'@shopkeeper.shahkotpk.local';$hash=password_hash($temp,PASSWORD_DEFAULT);$data=['name'=>$businessName.' Shopkeeper','email'=>$email,'phone'=>$phone,'password'=>$hash,'password_hash'=>$hash,'role'=>'seller','role_key'=>'seller','status'=>'active','is_verified'=>0,'verified'=>0,'must_reset_password'=>1];$uid=bs1270_insert('users',$data);if($uid<1)throw new RuntimeException('Unable to create shopkeeper user.');if(function_exists('bm1140_ensure_membership'))bm1140_ensure_membership($uid);elseif(bs1270_table('tenant_members')&&bs1270_tid()>0){try{bs1270_insert('tenant_members',['tenant_id'=>bs1270_tid(),'user_id'=>$uid,'member_role'=>'manager','role_key'=>'seller','role'=>'seller','status'=>1]);}catch(Throwable $e){}}return $uid;}
function bs1270_store_credential(int $bid,int $uid,string $temp): void {if(!bs1270_table('business_source_credentials_v1270'))return;$cipher=bs1270_encrypt($temp);try{bs1270_insert('business_source_credentials_v1270',['tenant_id'=>bs1270_tid(),'business_id'=>$bid,'user_id'=>$uid,'credential_cipher'=>$cipher,'created_at'=>date('Y-m-d H:i:s')]);}catch(Throwable $e){}}
function bs1270_import_candidate(int $candidateId,bool $force=false): array {$live=bs1270_live_candidate($candidateId);$c=$live['candidate'];$g=$live['google'];$web=$live['website'];$geo=$live['geo'];if(!$geo['ok'])throw new RuntimeException('Import blocked: place is outside the strict Shahkot, Punjab, Pakistan boundary.');if(empty($web['verified'])&&!$force)throw new RuntimeException('Import blocked: an official Shahkot business website could not be verified. Review the candidate manually in the existing Business Manager instead.');if(empty($web['verified']))throw new RuntimeException('Force import of Google-only content is disabled to prevent wrong/cached third-party data.');$match=(int)($live['matched_business_id']??0);if($match>0){bs1270_link_business($match,(string)$c['provider_place_id'],'official_website');if(function_exists('bs1273_mark_business_source'))bs1273_mark_business_source($match,false,bs1273_business_owner_id($match),'matched');bs1270_update('business_source_candidates_v1270',$candidateId,['status'=>'matched','matched_business_id'=>$match,'updated_at'=>date('Y-m-d H:i:s')]);return ['business_id'=>$match,'user_id'=>0,'temp_password'=>'','matched'=>true];}$settings=bs1270_setting_row();$temp=bs1270_random_password();$uid=!empty($settings['create_shopkeeper'])?bs1270_user_create((string)$web['name'],$web,$temp):0;if($uid<1)throw new RuntimeException('Shopkeeper account could not be created.');$bm=dirname(__DIR__).'/app/business_admin_v1140.php';if(is_file($bm))require_once $bm;if(!function_exists('bm1140_save'))throw new RuntimeException('Existing Professional Business Manager helper is unavailable.');$p=['business_id'=>0,'name'=>(string)$web['name'],'slug'=>'','category_id'=>(int)($c['category_id']??0),'city_id'=>0,'tagline'=>'','description'=>'','owner_user_id'=>$uid,'phone'=>(string)($web['phone']??''),'whatsapp'=>(string)($web['phone']??''),'email'=>(string)($web['email']??''),'website'=>(string)($web['website']??''),'address'=>(string)($web['address']??''),'area'=>'Shahkot','latitude'=>(string)($web['latitude']??''),'longitude'=>(string)($web['longitude']??''),'map_url'=>'','services'=>'','gallery_urls'=>'','image_existing'=>(string)($web['image']??''),'create_marketplace_shop'=>!empty($settings['create_marketplace_shop'])?1:0,'microsite_enabled'=>!empty($settings['create_business_website'])?1:0,'microsite_ai'=>1,'microsite_theme'=>'auto','verified'=>0,'featured'=>0,'status'=>!empty($settings['auto_publish_verified'])?'active':'pending','internal_notes'=>'Imported by Shahkot Business Data Extractor v12.7.0 after official-website verification. Google place ID is retained only as a source identifier; Google Places content is not persistently copied.'];$r=bm1140_save($p);$bid=(int)($r['id']??0);if($bid<1)throw new RuntimeException('Business creation failed.');bs1270_link_business($bid,(string)$c['provider_place_id'],'official_website');if(function_exists('bs1273_mark_business_source'))bs1273_mark_business_source($bid,true,$uid,'imported');bs1270_update('business_source_candidates_v1270',$candidateId,['status'=>'imported','matched_business_id'=>$bid,'confidence'=>(int)$live['confidence'],'website_verified'=>1,'updated_at'=>date('Y-m-d H:i:s')]);bs1270_store_credential($bid,$uid,$temp);bs1270_audit('candidate.imported',$bid,$candidateId,['user_id'=>$uid,'category_id'=>(int)($c['category_id']??0),'marketplace'=>!empty($settings['create_marketplace_shop'])?1:0,'microsite'=>!empty($settings['create_business_website'])?1:0]);return ['business_id'=>$bid,'user_id'=>$uid,'temp_password'=>$temp,'matched'=>false];}
function bs1270_link_business(int $bid,string $placeId,string $mode): void {$tid=bs1270_tid();try{$q=db()->prepare('SELECT id FROM business_source_links_v1270 WHERE tenant_id=? AND provider=? AND provider_place_id=? LIMIT 1');$q->execute([$tid,'google_places',$placeId]);$id=(int)($q->fetchColumn()?:0);$d=['tenant_id'=>$tid,'business_id'=>$bid,'provider'=>'google_places','provider_place_id'=>$placeId,'verification_mode'=>$mode,'last_source_check_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')];if($id)bs1270_update('business_source_links_v1270',$id,$d);else{$d['created_at']=date('Y-m-d H:i:s');bs1270_insert('business_source_links_v1270',$d);}}catch(Throwable $e){}}
function bs1270_sync_business(int $bid): array {
 if($bid<1)throw new RuntimeException('Invalid business.');
 try{$q=db()->prepare('SELECT * FROM business_source_links_v1270 WHERE tenant_id IN (?,0) AND business_id=? AND provider=? ORDER BY tenant_id DESC,id DESC LIMIT 1');$q->execute([bs1270_tid(),$bid,'google_places']);$link=$q->fetch()?:[];}catch(Throwable $e){$link=[];}
 if(!$link)throw new RuntimeException('No Google source link for this business.');
 $g=bs1270_google_detail((string)$link['provider_place_id']);
 $geo=bs1270_shahkot_check($g);
 if(!$geo['ok'])throw new RuntimeException('Google source no longer matches the strict Shahkot boundary; local business data was not changed.');
 // A live Google check is still useful even when no durable official-site fields are available.
 bs1270_update('business_source_links_v1270',(int)$link['id'],['last_source_check_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);
 $url=trim((string)($g['websiteUri']??''));
 if($url===''){
  bs1270_audit('business.source_checked',$bid,0,['google_place_verified'=>1,'official_website'=>0]);
  return ['business_id'=>$bid,'fields'=>[],'source_verified'=>true,'website_synced'=>false,'message'=>'Google Place was re-verified live for Shahkot. No official website is listed, so persistent business fields were left unchanged.'];
 }
 $web=bs1270_fetch_official_website($url,(string)($g['displayName']['text']??''));
 if(empty($web['verified'])){
  bs1270_audit('business.source_checked',$bid,0,['google_place_verified'=>1,'official_website'=>0,'website_error'=>(string)($web['error']??'verification failed')]);
  return ['business_id'=>$bid,'fields'=>[],'source_verified'=>true,'website_synced'=>false,'message'=>'Google Place was re-verified live. The linked website could not be confidently verified, so no local business fields were overwritten.'];
 }
 if(!bs1270_table('businesses'))throw new RuntimeException('Businesses table unavailable.');
 $d=['name'=>$web['name'],'phone'=>$web['phone'],'whatsapp'=>$web['phone'],'email'=>$web['email'],'website'=>$web['website'],'address'=>$web['address'],'latitude'=>$web['latitude'],'longitude'=>$web['longitude'],'image'=>$web['image'],'image_url'=>$web['image'],'cover_url'=>$web['image']];
 $d=array_filter($d,fn($v)=>$v!==''&&$v!==null);
 if(function_exists('bm1140_update'))bm1140_update('businesses',$bid,$d);else bs1270_update('businesses',$bid,$d);
 bs1270_update('business_source_links_v1270',(int)$link['id'],['last_source_check_at'=>date('Y-m-d H:i:s'),'last_website_sync_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);
 bs1270_audit('business.synced',$bid,0,['fields'=>array_keys($d)]);
 return ['business_id'=>$bid,'fields'=>array_keys($d),'source_verified'=>true,'website_synced'=>true,'message'=>'Google source and official business website were verified; safe persistent fields were synced.'];
}
function bs1270_sync_batch(int $limit=3): array {
 $limit=max(1,min(5,$limit));$rows=bs1270_linked_businesses($limit);$ok=0;$website=0;$errors=[];
 foreach($rows as $r){try{$x=bs1270_sync_business((int)$r['business_id']);$ok++;if(!empty($x['website_synced']))$website++;}catch(Throwable $e){$errors[]='Business #'.(int)$r['business_id'].': '.$e->getMessage();}}
 return ['checked'=>$ok,'website_synced'=>$website,'errors'=>$errors];
}

function bs1270_credential_for_business(int $bid): string {if($bid<1||!bs1270_table('business_source_credentials_v1270'))return '';try{$q=db()->prepare('SELECT * FROM business_source_credentials_v1270 WHERE tenant_id IN (?,0) AND business_id=? ORDER BY id DESC LIMIT 1');$q->execute([bs1270_tid(),$bid]);$r=$q->fetch()?:[];if(!$r)return '';$plain=bs1270_decrypt((string)($r['credential_cipher']??''));if($plain!==''&&empty($r['revealed_at']))bs1270_update('business_source_credentials_v1270',(int)$r['id'],['revealed_at'=>date('Y-m-d H:i:s')]);return $plain;}catch(Throwable $e){return '';}}
function bs1270_auto_process_one(): array {$s=bs1270_setting_row();if(empty($s['enabled'])||empty($s['auto_publish_verified']))return ['status'=>'disabled'];$rows=bs1270_candidates('discovered',1);if(!$rows)return ['status'=>'empty'];$cid=(int)$rows[0]['id'];try{$live=bs1270_live_candidate($cid);if(!empty($live['website']['verified'])&&!empty($live['geo']['ok'])&&(int)$live['confidence']>=90){$r=bs1270_import_candidate($cid);return ['status'=>'imported','candidate_id'=>$cid,'business_id'=>(int)($r['business_id']??0)];}return ['status'=>'review','candidate_id'=>$cid,'confidence'=>(int)$live['confidence']];}catch(Throwable $e){bs1270_update('business_source_candidates_v1270',$cid,['last_error'=>mb_substr($e->getMessage(),0,500),'last_checked_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);return ['status'=>'error','candidate_id'=>$cid,'error'=>$e->getMessage()];}}
function bs1270_linked_businesses(int $limit=100): array {if(!bs1270_table('business_source_links_v1270'))return [];try{$q=db()->prepare('SELECT l.*,b.name business_name,b.phone business_phone FROM business_source_links_v1270 l LEFT JOIN businesses b ON b.id=l.business_id WHERE l.tenant_id IN (?,0) ORDER BY l.id DESC LIMIT '.max(1,min(300,$limit)));$q->execute([bs1270_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function bs1270_stats(): array {$o=['candidates'=>0,'verified'=>0,'imported'=>0,'linked'=>0];try{$tid=bs1270_tid();$q=db()->prepare('SELECT COUNT(*),SUM(status IN (\'verified\',\'matched\',\'imported\')),SUM(status=\'imported\') FROM business_source_candidates_v1270 WHERE tenant_id IN (?,0)');$q->execute([$tid]);$r=$q->fetch(PDO::FETCH_NUM)?:[0,0,0];$o['candidates']=(int)$r[0];$o['verified']=(int)$r[1];$o['imported']=(int)$r[2];$q=db()->prepare('SELECT COUNT(*) FROM business_source_links_v1270 WHERE tenant_id IN (?,0)');$q->execute([$tid]);$o['linked']=(int)$q->fetchColumn();}catch(Throwable $e){}return $o;}
}
